import os
import google.generativeai as genai

def check_annotation_safety(text: str) -> dict:
    """
    Checks free-text metric labels or annotations for unsafe text using Google Generative AI.
    """
    api_key = os.environ.get("GOOGLE_API_KEY")
    if not api_key:
        raise ValueError("GOOGLE_API_KEY environment variable not set.")

    genai.configure(api_key=api_key)

    # Use a Generative AI model that supports safety attributes
    model = genai.GenerativeModel('gemini-pro')

    response = model.generate_content(text, safety_settings=[
        {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
        {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
    ])

    safety_ratings = {}
    if hasattr(response, 'prompt_feedback') and response.prompt_feedback.safety_ratings:
        for rating in response.prompt_feedback.safety_ratings:
            safety_ratings[rating.category.name] = rating.probability.name

    return {"text": text, "safety_ratings": safety_ratings}

from google.cloud import monitoring_v3
from datetime import datetime, timedelta

def summarize_metric_trends(project_id: str, metric_type: str, minutes: int = 60):
    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    now = datetime.utcnow()
    end_time = now.strftime("%Y-%m-%dT%H:%M:%SZ")
    start_time = (now - timedelta(minutes=minutes)).strftime("%Y-%m-%dT%H:%M:%SZ")

    query = f"""
        fetch {metric_type.split("/")[0]}
        | metric {metric_type}
        | group_by [], [value_mean: mean(value)]
        | within d'{start_time}', d'{end_time}'
    """

    try:
        response = client.query_time_series(
            request={
                "name": project_name,
                "query": query,
            }
        )

        summary_data = []
        for time_series in response.time_series_data:
            for point in time_series.points:
                summary_data.append({
                    "timestamp": point.interval.end_time.strftime("%Y-%m-%dT%H:%M:%SZ"),
                    "value": point.value.double_value
                })

        # Placeholder for actual trend/anomaly summarization logic
        if summary_data:
            return f"Successfully retrieved {len(summary_data)} data points for metric {metric_type}. Further analysis would summarize trends or anomalies."
        else:
            return f"No data found for metric {metric_type} in the last {minutes} minutes."

    except Exception as e:
        return f"Error summarizing metric trends: {e}

import dataclasses
from datetime import datetime
from typing import Any, Dict, List, Optional, Union

@dataclasses.dataclass
class Label:
    key: str
    value: str

@dataclasses.dataclass
class Metric:
    name: str
    labels: Optional[List[Label]] = None

@dataclasses.dataclass
class Datapoint:
    timestamp: datetime
    value: Union[int, float]

@dataclasses.dataclass
class TimeSeries:
    metric: Metric
    points: List[Datapoint]

@dataclasses.dataclass
class QueryRequest:
    metric_name: str
    start_time: datetime
    end_time: datetime
    interval_seconds: Optional[int] = None
    filters: Optional[Dict[str, str]] = None

@dataclasses.dataclass
class QueryResponse:
    time_series: List[TimeSeries]

def normalize_time_series(
    series_list: List[TimeSeries],
    start_time: datetime,
    end_time: datetime,
    interval_seconds: int,
    fill_value: Union[int, float, None] = None
) -> List[TimeSeries]:
    """
    Normalizes a list of TimeSeries to a common time window and interval.
    Missing data points within the window are filled with fill_value.
    """
    normalized_series_list = []

    for series in series_list:
        normalized_points: List[Datapoint] = []
        current_time = start_time
        series_points_map = {dp.timestamp: dp.value for dp in series.points}

        while current_time <= end_time:
            value = series_points_map.get(current_time, fill_value)
            if value is not None:
                normalized_points.append(Datapoint(timestamp=current_time, value=value))
            current_time = current_time + timedelta(seconds=interval_seconds)

        normalized_series_list.append(TimeSeries(metric=series.metric, points=normalized_points))

    return normalized_series_list

